  3	  "version": "1.0.0",
  4	  "private": true,
  5	  "type": "module",
  6	  "description": "Deliberately small order-management API used as the worked project throughout Graph Engineering with AI Agents.",
  7	  "engines": {
  8	    "node": ">=20"
  9	  },
 10	  "scripts": {
 11	    "test": "node --test",
 12	    "test:module": "node --test",
 13	    "lint": "node scripts/lint.js",
 14	    "format": "node scripts/lint.js --fix"
 15	  }
 16	}
 17	// Calls every handler in src/api/routes.js the way the router does, with a
 18	// request object and a callback, and reports whether each one answers.
 19	// The unit tests call service functions directly, so a change to a service's
 20	// signature can pass them while the router can no longer reach it.
 21	// Exits 1 if any route errors or never calls back.
 22	import { routes } from '../src/api/routes.js';
 23	
 24	const TIMEOUT_MS = 1500;
 25	let broken = 0;
 26	
 27	for (const route of routes) {
 28	  const outcome = await new Promise((resolve) => {
 29	    const timer = setTimeout(() => resolve({ ok: false, text: 'NO RESPONSE (callback never called)' }), TIMEOUT_MS);
 30	    try {
 31	      route.handler({ params: { id: '1' } }, (err, data) => {
 32	        clearTimeout(timer);
 33	        if (err) resolve({ ok: false, text: `error: ${err.message}` });
 34	        else resolve({ ok: true, text: JSON.stringify(data).slice(0, 60) });
 35	      });
 36	    } catch (err) {
 37	      clearTimeout(timer);
 38	      resolve({ ok: false, text: `threw: ${err.message}` });
 39	    }
 40	  });
 41	  if (!outcome.ok) broken += 1;
 42	  console.log(`${outcome.ok ? 'ok  ' : 'FAIL'}  ${route.method} ${route.path} -> ${outcome.text}`);
 43	}
 44	
 45	console.log(broken ? `${broken} of ${routes.length} routes broken` : `all ${routes.length} routes respond`);
 46	process.exit(broken ? 1 : 0);
 47	#!/usr/bin/env node
 48	// A dependency-free stand-in for eslint and prettier, so the Chapter 6 hooks
 49	// have something real to run on a machine with no npm install.
 50	// Checks: no tab indentation, no trailing whitespace, file ends in one newline.
 51	import { readdirSync, readFileSync, writeFileSync, statSync } from 'node:fs';
 52	import { join } from 'node:path';
 53	
 54	const fix = process.argv.includes('--fix');
 55	const targets = process.argv.slice(2).filter((a) => !a.startsWith('--'));
 56	
 57	function walk(dir) {
 58	  return readdirSync(dir).flatMap((e) => {
 59	    const p = join(dir, e);
 60	    if (statSync(p).isDirectory()) return walk(p);
 61	    return p.endsWith('.js') ? [p] : [];
 62	  });
 63	}
 64	
 65	const files = targets.length ? targets : [...walk('src'), ...walk('tests')];
 66	let problems = 0;
 67	
 68	for (const f of files) {
 69	  const before = readFileSync(f, 'utf8');
 70	  let after = before.replace(/\t/g, '  ').replace(/[ \t]+$/gm, '');
 71	  if (!after.endsWith('\n')) after += '\n';
 72	  after = after.replace(/\n{3,}$/, '\n');
 73	  if (after !== before) {
 74	    if (fix) writeFileSync(f, after);
 75	    else { console.error(`${f}: formatting`); problems += 1; }
 76	  }
 77	}
 78	
 79	if (problems && !fix) {
 80	  console.error(`${problems} file(s) need formatting. Run: npm run format`);
 81	  process.exit(1);
 82	}
 83	console.log(fix ? `formatted ${files.length} file(s)` : `${files.length} file(s) clean`);
 84	import { query } from '../db.js';
 85	
 86	// Callback-style database access. Chapter 5 migrates this to UserRepository.
 87	export function findByEmail(email, callback) {
 88	  query('users', (u) => u.email === email && u.deleted_at === null, (err, rows) => {
 89	    if (err) return callback(err);
 90	    callback(null, rows[0] ?? null);
 91	  });
 92	}
 93	
 94	export function isActive(email, callback) {
 95	  findByEmail(email, (err, user) => {
 96	    if (err) return callback(err);
 97	    callback(null, Boolean(user));
 98	  });
 99	}
100	import { query } from '../db.js';
101	
102	// Callback-style database access. Chapter 5 migrates this to OrderRepository.
103	export function listOrdersForUser(userId, callback) {
104	  query('orders', (o) => o.user_id === userId && o.deleted_at === null, callback);
105	}
106	
107	export function totalPaidCents(callback) {
108	  query('orders', (o) => o.status === 'paid' && o.deleted_at === null, (err, rows) => {
109	    if (err) return callback(err);
110	    callback(null, rows.reduce((sum, o) => sum + o.total_cents, 0));
111	  });
112	}
113	import { query } from '../db.js';
114	
115	// Callback-style database access. Chapter 5 migrates this to a PaymentRepository
116	// the reader adds, which is the part of the exercise with no worked answer.
117	export function findPaymentsForOrder(orderId, callback) {
118	  query('payments', (p) => p.order_id === orderId, callback);
119	}
120	
121	export function uncapturedTotalCents(callback) {
122	  query('payments', (p) => p.captured === false, (err, rows) => {
123	    if (err) return callback(err);
124	    callback(null, rows.reduce((sum, p) => sum + p.amount_cents, 0));
125	  });
126	}
127	import { query, update } from '../db.js';
128	
129	// Callback-style database access. Chapter 5 migrates this to UserRepository.
130	export function listActiveUsers(callback) {
131	  query('users', (u) => u.deleted_at === null, callback);
132	}
133	
134	export function findUser(id, callback) {
135	  query('users', (u) => u.id === id, (err, rows) => {
136	    if (err) return callback(err);
137	    callback(null, rows[0] ?? null);
138	  });
139	}
140	
141	export function softDeleteUser(id, when, callback) {
142	  update('users', id, { deleted_at: when }, callback);
143	}
144	// A deliberately tiny in-memory database with a callback API.
145	// The callback style is the point: Chapter 5 migrates the service layer off it.
146	
147	const tables = {
148	  users: [
149	    { id: 1, email: 'ada@example.com', name: 'Ada', deleted_at: null },
150	    { id: 2, email: 'grace@example.com', name: 'Grace', deleted_at: null },
151	    { id: 3, email: 'alan@example.com', name: 'Alan', deleted_at: '2026-01-04' },
152	  ],
153	  orders: [
154	    { id: 10, user_id: 1, total_cents: 4200, status: 'paid', deleted_at: null },
155	    { id: 11, user_id: 1, total_cents: 1350, status: 'quote', deleted_at: null },
156	    { id: 12, user_id: 2, total_cents: 9900, status: 'paid', deleted_at: null },
157	    { id: 13, user_id: 3, total_cents: 500, status: 'paid', deleted_at: null },
158	  ],
159	  payments: [
160	    { id: 100, order_id: 10, amount_cents: 4200, captured: true },
161	    { id: 101, order_id: 12, amount_cents: 9900, captured: false },
162	  ],
163	};
164	
165	export function reset() {
166	  tables.users[2].deleted_at = '2026-01-04';
167	  tables.orders.forEach((o) => { o.deleted_at = null; });
168	}
169	
170	// Old-style callback query. Accepts a table name and a predicate.
171	export function query(table, predicate, callback) {
172	  setImmediate(() => {
173	    const rows = tables[table];
174	    if (!rows) return callback(new Error(`no such table: ${table}`));
175	    try {
176	      callback(null, rows.filter(predicate).map((r) => ({ ...r })));
177	    } catch (err) {
178	      callback(err);
179	    }
180	  });
181	}
182	
183	export function update(table, id, patch, callback) {
184	  setImmediate(() => {
185	    const row = (tables[table] || []).find((r) => r.id === id);
186	    if (!row) return callback(new Error(`no row ${id} in ${table}`));
187	    Object.assign(row, patch);
188	    callback(null, { ...row });
189	  });
190	}

